"""Static PWA presentation assets and contract helpers for ZEN Control."""

from __future__ import annotations

import base64

PWA_RELEASE = "0.54.5.1"

_ICON_BASE64 = {
    180: "",
    192: "",
    512: "",
}


def icon_png(size: int) -> bytes:
    """Return one of the embedded install icons without filesystem mutation."""
    if size not in _ICON_BASE64:
        raise KeyError(size)
    return base64.b64decode(_ICON_BASE64[size])


def status_contract(version: str) -> dict:
    return {
        "schema": "zen_pwa_status_v1",
        "version": version,
        "mode": "online_first",
        "service_worker_scope": "/",
        "cached_private_data": False,
        "offline_mutations": False,
        "background_sync": False,
        "push_notifications": False,
        "server_auth_required": True,
        "shared_display_lock_server_enforced": True,
    }
